import{_ as t,o as e,c as r,ah as n}from"./chunks/framework.rk_qxSDs.js";const p=JSON.parse('{"title":"Decorators Configuration","description":"The options of the decorators plugin.","frontmatter":{"title":"Decorators Configuration","description":"The options of the decorators plugin.","relatedPlugins":["body","cookie","query"]},"headers":[],"relativePath":"decorators/configuration.md","filePath":"decorators/configuration.md","lastUpdated":1795602954000}'),a={name:"decorators/configuration.md"};function i(s,o,c,l,d,h){return e(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>decorators(options)</code> takes one option, the controllers to mount. Register the plugin with <code>app.use()</code>, with or without a path (<a href="https://routup.dev/guide/plugins" target="_blank" rel="noreferrer">Plugins</a>).</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>controllers</code></td><td><code>(ClassType | Record&lt;string, any&gt;)[]</code></td><td>required</td><td>Controller classes, or controller instances, to mount when the plugin is installed</td></tr></tbody></table><h3 id="controllers" tabindex="-1"><code>controllers</code> <a class="header-anchor" href="#controllers" aria-label="Permalink to &quot;`controllers`&quot;">​</a></h3><ul><li><strong>A class</strong> is created once per install with <code>new Controller()</code>, without constructor arguments. There is no dependency injection.</li><li><strong>An instance</strong> is used as it is: pass one when the controller needs constructor arguments, as in <code>controllers: [new TodoController(repository)]</code> (<a href="/decorators/recipes#a-crud-controller">CRUD recipe</a>).</li><li>Each controller&#39;s routes are added under each of its <code>@DController()</code> paths, in the order of the array, at the position of <code>app.use()</code>. A controller and functional handlers can share the app.</li><li>A class or instance without any decorator adds nothing.</li></ul>',6)])])}const f=t(a,[["render",i]]);export{p as __pageData,f as default};
